const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const fail=(message,status=400)=>{throw Object.assign(new Error(message),{status});};
const hash=async s=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))),v=>v.toString(16).padStart(2,'0')).join('');
async function body(req,max=4096){if(Number(req.headers.get('content-length'))>max)fail('입력 내용이 너무 길어요.',413);const txt=await req.text();if(txt.length>max)fail('입력 내용이 너무 길어요.',413);try{return JSON.parse(txt);}catch{fail('잘못된 요청이에요.');}}
const clean=(s,max)=>typeof s==='string'?s.trim().slice(0,max):'';
function person(b){const name=clean(b.name,20).normalize('NFKC'),stopId=clean(b.stopId,40);if(!name)fail('이름을 입력해주세요.');if(!validStops.has(stopId))fail('목록에서 출발 정류장을 선택해주세요.');return{name,stopId};}
async function mine(req,db,id){const user=await account(req,db);if(user){const me=await db.prepare('SELECT * FROM room_members WHERE room_id=? AND user_id=?').bind(id,user.id).first();if(me)return me;}const token=req.headers.get('authorization')?.replace(/^Bearer /,'');if(!token||token.length>200)return null;const member=await db.prepare('SELECT * FROM room_members WHERE room_id=? AND token_hash=?').bind(id,await hash(token)).first();if(member?.user_id&&member.user_id!==user?.id)return null;return member;}
async function readRoom(req,db,id){const room=await db.prepare('SELECT * FROM rooms WHERE id=?').bind(id).first();if(!room)fail('모임을 찾을 수 없어요. 링크를 확인해주세요.',404);const members=(await db.prepare('SELECT id,name,slot,stop_id,managed FROM room_members WHERE room_id=? ORDER BY slot').bind(id).all()).results;const me=await mine(req,db,id),creator=await rosterCreator(req,db,room);return{id:room.id,title:room.title,mode:room.mode,isOwner:await roomOwner(req,db,room),photoUrl:room.photo_key?'/api/rooms/'+id+'/photo?v='+encodeURIComponent(room.photo_key.split('/').at(-1)):null,members:members.map(m=>({id:m.id,name:m.name,slot:m.slot,ready:!!m.stop_id,managed:!!m.managed,canEdit:creator&&[1,2].includes(m.managed),editableStopId:creator&&[1,2].includes(m.managed)?m.stop_id:null,claimable:m.managed===2||(m.managed===1&&!m.stop_id)})),me:me?{id:me.id,name:me.name,stopId:me.stop_id}:null};}
const appWorker={async fetch(req,env){const url=new URL(req.url),p=url.pathname;try{if(p.startsWith('/auth/')||p.startsWith('/api/')){if(req.method!=='GET'&&!pagesRequest(req,env)&&((req.headers.get('origin')&&req.headers.get('origin')!==url.origin)||req.headers.get('sec-fetch-site')==='cross-site'))fail('다른 사이트에서의 요청은 허용하지 않아요.',403);if(!env.DB)fail('모임 저장소에 연결하지 못했어요.',503);const db=env.DB;const auth=await authRoutes(req,env);if(auth!==undefined)return auth;if(req.method!=='GET')await needAccount(req,env);const final=await finalRoutes(req,env);if(final!==undefined)return final;const extra=await roomAddons(req,env);if(extra!==undefined)return extra;
if(p==='/api/rooms'&&req.method==='POST'){const user=await account(req,db),b=await body(req),{name,stopId}=person(b),title=clean(b.title,60);if(!title)fail('모임 이름을 입력해주세요.');const mode=['버스만','통합','전체'].includes(b.mode)?b.mode:'통합',id=crypto.randomUUID(),memberId=crypto.randomUUID(),memberToken=crypto.randomUUID()+crypto.randomUUID();await db.batch([db.prepare('INSERT INTO rooms(id,title,mode,created_at) VALUES(?,?,?,?)').bind(id,title,mode,new Date().toISOString()),db.prepare('INSERT INTO room_members(id,room_id,token_hash,name,stop_id,slot,user_id) VALUES(?,?,?,?,?,0,?)').bind(memberId,id,await hash(memberToken),name,stopId,user?.id||null)]);return json({room:await readRoom(new Request(req.url,{headers:{cookie:req.headers.get('cookie')||'',Authorization:'Bearer '+memberToken,'X-Room-Owner-Token':req.headers.get('X-Room-Owner-Token')||''}}),db,id),memberToken},201);}
const m=p.match(/^\/api\/rooms\/([a-f0-9-]{36})(?:\/(join|me))?$/);if(!m)fail('요청한 기능을 찾을 수 없어요.',404);const [,id,action]=m;if(!action&&req.method==='GET')return json(await readRoom(req,db,id));
if(action==='join'&&req.method==='POST'){const user=await account(req,db);if(await mine(req,db,id))fail('이미 참여한 모임이에요. 내 정보를 수정해주세요.',409);const b=await body(req),{name,stopId}=person(b);if(!await db.prepare('SELECT id FROM rooms WHERE id=?').bind(id).first())fail('모임을 찾을 수 없어요.',404);const memberId=crypto.randomUUID(),memberToken=crypto.randomUUID()+crypto.randomUUID();try{await db.prepare('INSERT INTO room_members(id,room_id,token_hash,name,stop_id,slot,user_id) VALUES(?,?,?,?,?,COALESCE((SELECT slot+1 FROM room_members WHERE room_id=? ORDER BY slot DESC LIMIT 1),0),?)').bind(memberId,id,await hash(memberToken),name,stopId,id,user?.id||null).run();}catch(err){if(err.status)throw err;if(String(err).includes('UNIQUE'))fail('이미 쓰는 이름이에요. 구분할 수 있게 이름을 바꿔주세요.',409);throw err;}return json({room:await readRoom(new Request(req.url,{headers:{cookie:req.headers.get('cookie')||'',Authorization:'Bearer '+memberToken,'X-Room-Owner-Token':req.headers.get('X-Room-Owner-Token')||''}}),db,id),memberToken},201);}
if(action==='me'&&req.method==='PUT'){const me=await mine(req,db,id);if(!me)fail('내 참여 권한을 확인할 수 없어요. 참여한 브라우저에서 열어주세요.',401);const {name,stopId}=person(await body(req));try{await db.prepare('UPDATE room_members SET name=?,stop_id=? WHERE id=? AND room_id=?').bind(name,stopId,me.id,id).run();}catch(err){if(String(err).includes('UNIQUE'))fail('이미 쓰는 이름이에요.',409);throw err;}return json(await readRoom(req,db,id));}fail('지원하지 않는 요청이에요.',405);
}
const asset=assets[p==='/'||p==='/index.html'?'/':p];if(asset&&['GET','HEAD'].includes(req.method))return new Response(req.method==='HEAD'?null:asset.body,{headers:{'Content-Type':asset.type,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});return new Response('Not found',{status:404});
}catch(err){if(!err.status)console.error(JSON.stringify({event:'room_request_failed',action:p.split('/').at(-1),message:String(err.message||err).slice(0,500)}));return json({error:err.status?err.message:'처리하지 못했어요. 잠시 후 다시 시도해주세요.'},err.status||500);}}};

function pagesOrigin(env){return env.PAGES_ORIGIN||'https://kjjjk1.github.io';}
function pagesRequest(req,env){
 const origin=req.headers.get('origin');if(origin)return origin===pagesOrigin(env);
 try{return new URL(req.headers.get('referer')).origin===pagesOrigin(env);}catch{return false;}
}
export default {async fetch(req,env){
 const url=new URL(req.url),origin=req.headers.get('origin'),api=url.pathname.startsWith('/api/');
 const allowed=origin===pagesOrigin(env),foreign=origin&&origin!==url.origin;
 if((api||url.pathname.startsWith('/auth/'))&&foreign&&!allowed)return json({error:'허용되지 않은 사이트의 요청입니다.'},403);
 let response;
 if(api&&req.method==='OPTIONS'){
  if(!allowed)return json({error:'허용되지 않은 사이트의 요청입니다.'},403);
  const method=req.headers.get('access-control-request-method');
  const requested=(req.headers.get('access-control-request-headers')||'').toLowerCase().split(',').map(s=>s.trim()).filter(Boolean);
  if(!['GET','POST','PUT','DELETE','HEAD'].includes(method)||requested.some(h=>!['authorization','content-type','x-room-owner-token'].includes(h)))response=json({error:'허용되지 않은 요청입니다.'},403);
  else response=new Response(null,{status:204,headers:{'Access-Control-Allow-Methods':'GET, POST, PUT, DELETE, HEAD, OPTIONS','Access-Control-Allow-Headers':'Authorization, Content-Type, X-Room-Owner-Token','Access-Control-Max-Age':'600'}});
 }else response=await appWorker.fetch(req,env);
 if(api){const headers=new Headers(response.headers);headers.append('Vary','Origin');if(allowed)headers.set('Access-Control-Allow-Origin',origin);return new Response(response.body,{status:response.status,statusText:response.statusText,headers});}
 return response;
}};

async function rosterCreator(req,db,room){const user=await account(req,db);if(user&&room.creator_user_id===user.id)return true;const token=req.headers.get('X-Room-Owner-Token');return !!(room.roster_creator_hash&&token&&token.length<=200&&await hash(token)===room.roster_creator_hash);}
async function releaseBootstrap(req,db,id){const token=req.headers.get('X-Room-Owner-Token');if(token&&token.length<=200)await db.prepare('UPDATE rooms SET owner_hash=NULL WHERE id=? AND owner_hash=?').bind(id,await hash(token)).run();}
export async function roomOwner(req,db,room){if(await mine(req,db,room.id))return true;const user=await account(req,db);if(user&&room.creator_user_id===user.id)return true;const token=req.headers.get('X-Room-Owner-Token');return !!(room.owner_hash&&token&&token.length<=200&&await hash(token)===room.owner_hash);}
async function addonRoom(db,id){const r=await db.prepare('SELECT * FROM rooms WHERE id=?').bind(id).first();if(!r)fail('모임을 찾을 수 없어요.',404);return r;}
async function addonOwner(req,db,room){if(!await roomOwner(req,db,room))fail('모임에 참여한 뒤 관리할 수 있어요.',403);}
function addonJPEG(bytes){if(!bytes||bytes.length>200000||bytes.length<4||bytes[0]!==255||bytes[1]!==216||bytes[2]!==255)fail('사진 형식이나 크기를 확인해주세요. JPEG 사진은 200KB까지 저장할 수 있어요.');return bytes;}
function addonPhoto(data){if(!data)return null;if(typeof data!=='string'||!data.startsWith('data:image/jpeg;base64,'))fail('지원하지 않는 사진 형식이에요.');try{return addonJPEG(Uint8Array.from(atob(data.slice(23)),c=>c.charCodeAt(0)));}catch(e){if(e.status)throw e;fail('사진을 읽을 수 없어요.');}}
async function addonSavePhoto(env,id,bytes){if(!env.BUCKET)fail('사진 저장소에 연결하지 못했어요.',503);const key='room-covers/'+id+'/'+crypto.randomUUID()+'.jpg';await env.BUCKET.put(key,bytes,{httpMetadata:{contentType:'image/jpeg'}});await env.DB.prepare('UPDATE rooms SET photo_key=? WHERE id=?').bind(key,id).run();}
export async function roomAddons(req,env){const url=new URL(req.url),p=url.pathname,db=env.DB;
if(p==='/api/rooms'&&req.method==='POST'){const b=await body(req.clone(),300000);if(b.name||b.stopId)return undefined;const user=await account(req,db),title=clean(b.title,60),image=addonPhoto(b.photo);if(!title)fail('모임 이름을 입력해주세요.');if(image&&!env.BUCKET)fail('사진 저장소에 연결하지 못했어요.',503);const mode=['버스만','통합','전체'].includes(b.mode)?b.mode:'통합',id=crypto.randomUUID(),ownerToken=crypto.randomUUID()+crypto.randomUUID();await db.prepare('INSERT INTO rooms(id,title,mode,created_at,owner_hash,creator_user_id,roster_creator_hash) VALUES(?,?,?,?,?,?,?)').bind(id,title,mode,new Date().toISOString(),user?null:await hash(ownerToken),user?.id||null,await hash(ownerToken)).run();let photoWarning=null;if(image)try{await addonSavePhoto(env,id,image);}catch{photoWarning='모임은 만들었지만 사진을 저장하지 못했어요. 모임관리에서 다시 올려주세요.';}return json({room:await readRoom(new Request(req.url,{headers:{'X-Room-Owner-Token':ownerToken,cookie:req.headers.get('cookie')||''}}),db,id),ownerToken,photoWarning},201);}
const m=p.match(/^\/api\/rooms\/([a-f0-9-]{36})\/(photo|participants|join|settings)(?:\/([a-f0-9-]{36}))?$/);if(!m)return undefined;const [,id,action,participantId]=m;
if(action==='photo'&&req.method==='GET'){const room=await addonRoom(db,id);if(!room.photo_key||!env.BUCKET)return new Response('Not found',{status:404});const obj=await env.BUCKET.get(room.photo_key);if(!obj)return new Response('Not found',{status:404});return new Response(obj.body,{headers:{'Content-Type':'image/jpeg','Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'}});}
if(action==='photo'&&req.method==='PUT'){const room=await addonRoom(db,id);await addonOwner(req,db,room);if(Number(req.headers.get('content-length'))>200000)fail('사진이 너무 커요.',413);const bytes=addonJPEG(new Uint8Array(await req.arrayBuffer()));await addonSavePhoto(env,id,bytes);if(room.photo_key)try{await env.BUCKET.delete(room.photo_key);}catch{}return json(await readRoom(req,db,id));}
if(action==='settings'&&req.method==='PUT'){const room=await addonRoom(db,id);await addonOwner(req,db,room);const b=await body(req);if(!['버스만','통합','전체'].includes(b.mode))fail('교통수단을 선택해주세요.');await db.prepare('UPDATE rooms SET mode=? WHERE id=?').bind(b.mode,id).run();return json(await readRoom(req,db,id));}
if(action==='participants'&&req.method==='POST'){const room=await addonRoom(db,id);await addonOwner(req,db,room);const b=await body(req),name=clean(b.name,20).normalize('NFKC'),stopId=clean(b.stopId,40);if(!name)fail('추가할 참여자 이름을 입력해주세요.');if(stopId&&!validStops.has(stopId))fail('목록에서 출발 정류장을 선택해주세요.');try{await db.prepare("INSERT INTO room_members(id,room_id,token_hash,name,stop_id,slot,managed) VALUES(?,?,?,?,?,COALESCE((SELECT slot+1 FROM room_members WHERE room_id=? ORDER BY slot DESC LIMIT 1),0),?)").bind(crypto.randomUUID(),id,await hash(crypto.randomUUID()+crypto.randomUUID()),name,stopId,id,stopId?2:1).run();}catch(e){if(String(e).includes('UNIQUE'))fail('이미 추가된 이름이에요.',409);throw e;}return json(await readRoom(req,db,id),201);}
if(action==='participants'&&participantId&&req.method==='PUT'){
 const room=await addonRoom(db,id);if(!await rosterCreator(req,db,room))fail('모임을 만든 사람만 직접 추가한 참여자를 수정할 수 있어요.',403);
 const b=await body(req),name=clean(b.name,20).normalize('NFKC'),stopId=clean(b.stopId,40);
 if(!name)fail('이름을 입력해주세요.');if(stopId&&!validStops.has(stopId))fail('목록에서 정류장을 선택해주세요.');
 try{const changed=await db.prepare('UPDATE room_members SET name=?,stop_id=?,managed=? WHERE id=? AND room_id=? AND managed IN (1,2)').bind(name,stopId,stopId?2:1,participantId,id).run();if(!changed.meta.changes)fail('직접 추가 후 아직 본인이 참여하지 않은 사람만 수정할 수 있어요.',409);}catch(e){if(String(e).includes('UNIQUE'))fail('이미 추가된 이름이에요.',409);throw e;}
 return json(await readRoom(req,db,id));
}
if(action==='participants'&&participantId&&req.method==='DELETE'){const room=await addonRoom(db,id);await addonOwner(req,db,room);const r=await db.prepare('DELETE FROM room_members WHERE id=? AND room_id=?').bind(participantId,id).run();if(!r.meta.changes)fail('이미 나간 참여자이거나 모임에 없는 사람이에요.',404);return json(await readRoom(req,db,id));}
if(action==='join'&&req.method==='POST'){const user=await account(req,db),b=await body(req.clone());if(!b.memberId)return undefined;if(await mine(req,db,id))fail('이미 참여한 모임이에요.',409);const {name,stopId}=person(b);await addonRoom(db,id);const memberToken=crypto.randomUUID()+crypto.randomUUID(),r=await db.prepare("UPDATE room_members SET token_hash=?,stop_id=?,managed=3,user_id=? WHERE id=? AND room_id=? AND name=? AND ((managed=1 AND stop_id='') OR managed=2)").bind(await hash(memberToken),stopId,user?.id||null,clean(b.memberId,36),id,name).run();if(!r.meta.changes)fail('이미 참여했거나 이름이 바뀌었어요. 목록을 새로고침해주세요.',409);await releaseBootstrap(req,db,id);if(user)await db.prepare('UPDATE rooms SET creator_user_id=NULL WHERE id=? AND creator_user_id=?').bind(id,user.id).run();return json({room:await readRoom(new Request(req.url,{headers:{cookie:req.headers.get('cookie')||'',Authorization:'Bearer '+memberToken,'X-Room-Owner-Token':req.headers.get('X-Room-Owner-Token')||''}}),db,id),memberToken},201);}
return undefined;}

const sessionCookie='__Host-dts_session',stateCookie='__Host-dts_oauth';
const cookieValue=(req,key)=>req.headers.get('cookie')?.split(';').map(s=>s.trim()).find(s=>s.startsWith(key+'='))?.slice(key.length+1)||'';
const authConfigured=env=>!!(env.KAKAO_REST_API_KEY&&env.KAKAO_CLIENT_SECRET);
const authCookie=(key,value,seconds)=>`${key}=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${seconds}`;
function localReturn(value){if(typeof value!=='string'||!value.startsWith('/')||value.startsWith('//')||value.includes('\\')||/[\r\n]/.test(value))return '/';return value.slice(0,1000);}
async function account(req,db){const token=cookieValue(req,sessionCookie);if(!token||token.length>200)return null;return db.prepare('SELECT u.id,u.nickname FROM auth_sessions s JOIN app_users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>?').bind(await hash(token),Date.now()).first();}
async function needAccount(req,env){const user=await account(req,env.DB);return user;}
function authRedirect(path,cookies=[]){const headers=new Headers({'Location':path,'Cache-Control':'no-store','Referrer-Policy':'no-referrer'});cookies.forEach(c=>headers.append('Set-Cookie',c));return new Response(null,{status:303,headers});}
async function providerJSON(url,options){const res=await fetch(url,{...options,signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error('provider');return res.json();}
export async function authRoutes(req,env){const url=new URL(req.url),p=url.pathname,db=env.DB;
if(p==='/api/auth/session'&&req.method==='GET')return json({configured:authConfigured(env),user:await account(req,db)});
if(p==='/auth/kakao'&&req.method==='GET'){
 if(!authConfigured(env))return authRedirect('/?auth_error=not_configured');
 const state=crypto.randomUUID()+crypto.randomUUID();await db.prepare('DELETE FROM oauth_states WHERE expires_at<?').bind(Date.now()).run();await db.prepare('INSERT INTO oauth_states(state_hash,return_to,expires_at) VALUES(?,?,?)').bind(await hash(state),localReturn(url.searchParams.get('returnTo')),Date.now()+600000).run();
 const target=new URL('https://kauth.kakao.com/oauth/authorize');target.search=new URLSearchParams({response_type:'code',client_id:env.KAKAO_REST_API_KEY,redirect_uri:url.origin+'/auth/kakao/callback',state}).toString();return authRedirect(target.href,[authCookie(stateCookie,state,600)]);
}
if(p==='/auth/kakao/callback'&&req.method==='GET'){
 const clear=authCookie(stateCookie,'',0),state=url.searchParams.get('state')||'';
 if(!authConfigured(env)||!state||state.length>200||state!==cookieValue(req,stateCookie))return authRedirect('/?auth_error=invalid_state',[clear]);
 const row=await db.prepare('SELECT return_to,expires_at FROM oauth_states WHERE state_hash=?').bind(await hash(state)).first();const consumed=await db.prepare('DELETE FROM oauth_states WHERE state_hash=?').bind(await hash(state)).run();
 if(!row||!consumed.meta.changes||row.expires_at<Date.now())return authRedirect('/?auth_error=invalid_state',[clear]);
 const destination=localReturn(row.return_to),errorPath=code=>destination+(destination.includes('?')?'&':'?')+'auth_error='+code;
 if(url.searchParams.has('error'))return authRedirect(errorPath('cancelled'),[clear]);const code=url.searchParams.get('code');if(!code||code.length>1000)return authRedirect(errorPath('failed'),[clear]);
 try{
  const result=await providerJSON('https://kauth.kakao.com/oauth/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=utf-8'},body:new URLSearchParams({grant_type:'authorization_code',client_id:env.KAKAO_REST_API_KEY,client_secret:env.KAKAO_CLIENT_SECRET,redirect_uri:url.origin+'/auth/kakao/callback',code})});
  if(!result.access_token)throw Error('token');const profile=await providerJSON('https://kapi.kakao.com/v2/user/me',{headers:{Authorization:'Bearer '+result.access_token}});if(!profile.id||!/^\d+$/.test(String(profile.id)))throw Error('profile');
  const nickname=clean(profile.kakao_account?.profile?.nickname||profile.properties?.nickname,40)||'카카오 사용자';const providerId=String(profile.id);
  await db.prepare('INSERT INTO app_users(id,kakao_id,nickname,created_at) VALUES(?,?,?,?) ON CONFLICT(kakao_id) DO UPDATE SET nickname=excluded.nickname').bind(crypto.randomUUID(),providerId,nickname,new Date().toISOString()).run();const user=await db.prepare('SELECT id FROM app_users WHERE kakao_id=?').bind(providerId).first();
  const old=cookieValue(req,sessionCookie);if(old)await db.prepare('DELETE FROM auth_sessions WHERE token_hash=?').bind(await hash(old)).run();await db.prepare('DELETE FROM auth_sessions WHERE expires_at<?').bind(Date.now()).run();
  const token=crypto.randomUUID()+crypto.randomUUID();await db.prepare('INSERT INTO auth_sessions(token_hash,user_id,expires_at) VALUES(?,?,?)').bind(await hash(token),user.id,Date.now()+604800000).run();return authRedirect(destination,[clear,authCookie(sessionCookie,token,604800)]);
 }catch{return authRedirect(errorPath('failed'),[clear]);}
}
if(p==='/api/auth/logout'&&req.method==='POST'){const token=cookieValue(req,sessionCookie);if(token)await db.prepare('DELETE FROM auth_sessions WHERE token_hash=?').bind(await hash(token)).run();return new Response(JSON.stringify({ok:true}),{headers:{'Content-Type':'application/json','Cache-Control':'no-store','Set-Cookie':authCookie(sessionCookie,'',0)}});}
if(p==='/api/account/rooms'&&req.method==='GET'){const user=await account(req,db);if(!user)fail('로그인 후 확인할 수 있어요.',401);const rows=await db.prepare('SELECT DISTINCT r.id FROM rooms r LEFT JOIN room_members m ON m.room_id=r.id WHERE m.user_id=? OR r.creator_user_id=? ORDER BY r.created_at DESC').bind(user.id,user.id).all();return json({ids:rows.results.map(r=>r.id)});}
if(p==='/api/recovery/restore'&&req.method==='POST'){
 const b=await body(req),code=typeof b.code==='string'?b.code.trim():'';
 if(!/^[a-f0-9]{64}$/.test(code))fail('복구 코드를 확인해주세요.',403);
 const row=await db.prepare('SELECT room_id FROM access_recovery WHERE code_hash=? AND expires_at>?').bind(await hash(code),Date.now()).first();
 if(!row)fail('코드가 만료되었거나 이미 사용·재발급되었습니다.',403);
 const target=new URL(req.url);target.pathname='/api/rooms/'+row.room_id+'/recovery/restore';
 const response=await authRoutes(new Request(target,{method:'POST',headers:req.headers,body:JSON.stringify({code})}),env);
 return json({...await response.json(),roomId:row.room_id},response.status);
}
const recovery=p.match(/^\/api\/rooms\/([a-f0-9-]{36})\/recovery\/(issue|restore)$/);
if(recovery&&req.method==='POST'){
 const [,id,action]=recovery,b=await body(req),room=await db.prepare('SELECT * FROM rooms WHERE id=?').bind(id).first();
 if(!room)fail('모임을 찾을 수 없어요.',404);
 if(action==='issue'){
  const role=b.role==='owner'?'owner':'member';let subject;
  if(role==='member'){subject=await mine(req,db,id);if(!subject)fail('본인 참여 권한이 필요해요.',403);if(subject.user_id)fail('계정에 연결된 참여 정보는 카카오 로그인으로 복원해주세요.',409);}
  else{if(!await rosterCreator(req,db,room))fail('모임 생성자만 발급할 수 있어요.',403);if(room.creator_user_id)fail('계정에 연결된 모임은 카카오 로그인으로 복원해주세요.',409);subject={id};}
  const code=crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-',''),expiresAt=Date.now()+365*86400000;
  await db.prepare('INSERT INTO access_recovery(room_id,subject_id,role,code_hash,expires_at) VALUES(?,?,?,?,?) ON CONFLICT(room_id,subject_id,role) DO UPDATE SET code_hash=excluded.code_hash,expires_at=excluded.expires_at').bind(id,subject.id,role,await hash(code),expiresAt).run();
  return json({code,role,expiresAt});
 }
 const code=typeof b.code==='string'?b.code.trim():'';
 if(!/^[a-f0-9]{64}$/.test(code))fail('복구 코드를 확인해주세요.',403);
 const digest=await hash(code),row=await db.prepare('SELECT * FROM access_recovery WHERE room_id=? AND code_hash=? AND expires_at>?').bind(id,digest,Date.now()).first();
 if(!row)fail('코드가 만료되었거나 이미 사용·재발급되었습니다.',403);
 if(row.role==='member'){
  const m=await db.prepare('SELECT * FROM room_members WHERE room_id=? AND id=?').bind(id,row.subject_id).first();
  if(!m||m.user_id)fail('카카오 로그인 또는 기존 참여 정보를 확인해주세요.',409);
  const current=await mine(req,db,id);if(current&&current.id!==m.id)fail('이미 다른 참여자로 접속 중입니다. 별도 브라우저에서 복구해주세요.',409);
 }else if(room.creator_user_id)fail('카카오 로그인으로 복원해주세요.',409);
 const token=crypto.randomUUID()+crypto.randomUUID(),tokenHash=await hash(token);
 const update=row.role==='member'?db.prepare('UPDATE room_members SET token_hash=? WHERE id=? AND room_id=? AND user_id IS NULL AND EXISTS(SELECT 1 FROM access_recovery WHERE code_hash=?)').bind(tokenHash,row.subject_id,id,digest):db.prepare('UPDATE rooms SET owner_hash=?,roster_creator_hash=? WHERE id=? AND creator_user_id IS NULL AND EXISTS(SELECT 1 FROM access_recovery WHERE code_hash=?)').bind(tokenHash,tokenHash,id,digest);
 const changes=await db.batch([update,db.prepare('DELETE FROM access_recovery WHERE code_hash=?').bind(digest)]);
 if(!changes[0].meta.changes)fail('이미 사용된 코드입니다.',409);
 return json(row.role==='member'?{memberToken:token}:{ownerToken:token});
}
const link=p.match(/^\/api\/rooms\/([a-f0-9-]{36})\/account$/);
if(link&&req.method==='POST'){
 const user=await account(req,db);if(!user)fail('로그인 후 연결해주세요.',401);const id=link[1],token=req.headers.get('authorization')?.replace(/^Bearer /,'');let linked=false;
 if(token&&token.length<=200){const member=await db.prepare('SELECT id,user_id FROM room_members WHERE room_id=? AND token_hash=?').bind(id,await hash(token)).first();if(member){if(member.user_id&&member.user_id!==user.id)fail('다른 계정에 연결된 참여 정보예요.',409);try{await db.prepare('UPDATE room_members SET user_id=? WHERE id=? AND (user_id IS NULL OR user_id=?)').bind(user.id,member.id,user.id).run();linked=true;}catch{fail('이 계정은 이미 다른 이름으로 참여했어요.',409);}}}
 const owner=req.headers.get('X-Room-Owner-Token');if(owner&&owner.length<=200){const r=await db.prepare('UPDATE rooms SET creator_user_id=?,owner_hash=NULL WHERE id=? AND owner_hash=? AND creator_user_id IS NULL').bind(user.id,id,await hash(owner)).run();linked=linked||!!r.meta.changes;}
 if(!linked)fail('연결할 기존 참여 권한을 확인할 수 없어요.',403);await db.prepare("DELETE FROM access_recovery WHERE room_id=? AND (role='owner' OR subject_id IN (SELECT id FROM room_members WHERE room_id=? AND user_id=?))").bind(id,id,user.id).run();const participant=await db.prepare('SELECT id FROM room_members WHERE room_id=? AND user_id=?').bind(id,user.id).first();if(participant)await db.prepare('UPDATE rooms SET creator_user_id=NULL WHERE id=? AND creator_user_id=?').bind(id,user.id).run();return json({ok:true});
}
return undefined;}

